diff --git a/src/infra/db/transaction.ts b/src/infra/db/transaction.ts
new file mode 100644
index 0000000..647059f
--- /dev/null
+++ b/src/infra/db/transaction.ts
@@ -0,0 +1,16 @@
+import type pg from 'pg';
+
+export async function inTransaction<T>(pool: pg.Pool, work: (client: pg.PoolClient) => Promise<T>): Promise<T> {
+  const client = await pool.connect();
+  try {
+    await client.query('begin');
+    const result = await work(client);
+    await client.query('commit');
+    return result;
+  } catch (error) {
+    await client.query('rollback');
+    throw error;
+  } finally {
+    client.release();
+  }
+}

